rtk .venv/bin/python -c "from quarkchain.env import Env; from quarkchain.cluster.cluster_config import ClusterConfig, update_genesis_alloc; from quarkchain.genesis import GenesisManager; from quarkchain.evm.state import State as EvmState; path='mainnet/singularity/cluster_config_template.json'; cc=ClusterConfig.from_json(open(path).read()); update_genesis_alloc(cc); env=Env(); env.cluster_config=cc; qkc=env.quark_chain_config; gm=GenesisManager(qkc); root=gm.create_root_block(); print('CONFIG', path); print('CHAIN_SIZE', qkc.CHAIN_SIZE); print('GENESIS_ROOT_HASH', '0x'+root.header.get_hash().hex());
for fsid in sorted(qkc.get_full_shard_ids()):
    st=EvmState(env=env.evm_env, db=env.db, qkc_config=qkc); st.shard_config=qkc.shards[fsid]; block, _=gm.create_minor_block(root, fsid, st); print('fullShardID=%-6d root=0x%s' % (fsid, block.meta.hash_evm_state_root.hex()))"